{
  "verdict": "request_changes",
  "summary": "candidate.py fails to raise ValueError for unknown tier strings, instead returning a default of 100.",
  "findings": [
    {
      "finding_id": "spec_violation_unknown_tier",
      "file": "candidate.py",
      "line_start": 3,
      "line_end": 3,
      "severity": "high",
      "description": "The specification mandates raising ValueError for any input that is not exactly 'basic' or 'premium'. The current implementation uses dict.get with a fallback default of 100, causing it to silently return 100 for invalid inputs instead of raising the required exception.",
      "evidence": "SPEC.md states: 'For every other string, raise ValueError.' candidate.py line 3 `return limits.get(tier, 100)` returns 100 when called with `quota('gold')`, violating the contract."
    }
  ]
}
